# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), проверено вычислением; условия сверены с текстом учебника (№10.53 а)"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_11_1_10_53_a", r"в учебнике $3\tg^{2}(\pi x-\frac{\pi}{8})=1$ (цифра $3$ была вынесена в «уравнения $3$:»): $\tg=\pm\frac{1}{\sqrt3}$, $x=\frac{7}{24}+k$ или $x=-\frac{1}{24}+k$; на $(\frac32;3)$: $\frac{47}{24},\frac{55}{24},\frac{71}{24}$ (в ключе стояли $\frac{43}{24}$ и $\frac{67}{24}$ — серия для $\tg=-\sqrt3$)",
  q=r"Найдите все решения уравнения $3\tg^{2}\left(\pi x - \dfrac{\pi}{8}\right) = 1$, принадлежащие промежутку $\left(\dfrac{3}{2}; 3\right)$.",
  k=r"$x=\dfrac{47}{24}; x=\dfrac{55}{24}; x=\dfrac{71}{24}$",
  dnew={0: (r"$x=\dfrac{47}{24}; x=\dfrac{55}{24}$", "Ученик верно нашёл серии $x=\\frac{7}{24}+k$ и $x=-\\frac{1}{24}+k$, но при отборе на $\\left(\\frac32;3\\right)$ потерял последний корень $\\frac{71}{24}$ ($k=3$)."),
        1: (r"$x = \dfrac{19}{24}; x = \dfrac{31}{24}; x = \dfrac{43}{24}$", "Ученик отобрал корни при $k=0,1,2$ подряд, не сверив их с промежутком $\\left(\\frac32;3\\right)$: $\\frac{19}{24}$ и $\\frac{31}{24}$ меньше $\\frac32$."),
        2: (r"$x=\dfrac{43}{24}; x=\dfrac{55}{24}; x=\dfrac{67}{24}$", "Ученик для серии $\\tg=-\\frac{1}{\\sqrt3}$ взял $\\arctg\\frac{1}{\\sqrt3}=\\frac{\\pi}{3}$ вместо $\\frac{\\pi}{6}$ и получил $\\frac{43}{24}$ и $\\frac{67}{24}$ вместо $\\frac{47}{24}$ и $\\frac{71}{24}$.")})
